INSERT INTO gdrive.drive_files (id, name, mime_type, parents_json, owner_email, shared_with_emails_json, visibility, owners_json, modified_time, created_time, trashed, starred)
VALUES ('f_4591ef30be4f920ba1ed14', 'Paid UA close rules - data room', 'application/vnd.google-apps.document', '["d_b563e7f1e1608c4d36f3b0"]', 'leonard.hayes@harmonygames.co', '["frederick.stone@harmonygames.co", "arthur.blake@harmonygames.co"]', 'private', '["leonard.hayes@harmonygames.co"]', '2025-09-26T21:05:00Z', '2025-09-26T20:40:00Z', false, false);
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_4591ef30be4f920ba1ed14', 'Paid UA close rules - data room', 'leonard.hayes@harmonygames.co', '["frederick.stone@harmonygames.co", "arthur.blake@harmonygames.co"]', 'private', E'Paid UA close rules - data room\nCovers the last twelve months, Oct 1, 2024 to Sep 30, 2025. This replaces the rough rules I emailed on the 19th.\n\nWhat counts\nMoney we spent buying users on the networks Frederick runs: Meta (our ad account ending 3125), Unity Ads (our account and the Calm Play one we run Zombie Match 3D from), Adjoe, AppLovin and Google UAC. Money a network pays us is not spend. My own Meta test account stays out of this.\n\nRows\nOne row per network, month, title and bucket.\n\nMeta\nUse the receipts, even where Snowflake shows something else. A charge paid with advertising credit cost us nothing. A receipt that arrives twice with the same reference number is one charge. Month is the charge date in Pacific time.\n\nUnity\nWe prepay Unity, so a top-up is not spend. Spend is what Unity''s statements say we used that month.\n\nAdjoe\nUse the ledger amount for each invoice, it already has any credit Adjoe gave us. Adjoe goes in the month we wired the payment.\n\nAppLovin and Google UAC\nTake the monthly amounts from the ledger. Where a month ran on both games, split it by game the way AD_SPEND_DAILY does. Don''t net AppLovin against our MAX payouts.\n\nTitles\nEach Meta test has a brief in the UA test briefs folder that says which game it was for.\n\nSnowflake check\nUnder the table, list every network and month where we spent money but Snowflake shows $0. The connector page on Confluence explains what Singular misses.\n\nWhen it''s done\nSend the sheet link to our outside accountant. She''s already on the data room folder as a viewer, so no new sharing. Not to investors.', '[{"start": 0, "end": 32, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 32, "end": 1583, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '249e7d4fa2', 'f_4591ef30be4f920ba1ed14', '2025-09-26T20:40:00Z', '2025-09-26T21:05:00Z');
