-- ===================== CONFLUENCE (re-verify after regeneration) =====================
INSERT INTO confluence.confluence_pages (id, space_id, parent_id, title, body, body_format, status, version, author_id, created_at, updated_at)
VALUES ('page_singular_cost_connectors', 'space_ENG', 'page_eng_home', 'Singular cost connectors', '<p>Which ad networks send cost into Singular. AD_SPEND_DAILY in Snowflake is built from Singular''s cost per network, and the marketing_ua amounts in FINANCE_LEDGER come from the same cost, so both have the gaps below. FINANCE_LEDGER books operating costs by month: marketing, salaries, AWS and the rest are dated to the last day of the month they belong to, not the day the money moved.</p><table><tbody><tr><th>Network</th><th>Cost into Singular</th><th>Notes</th></tr><tr><td>Adjoe</td><td>Yes</td><td>Loaded from the monthly invoice after any credit.</td></tr><tr><td>AppLovin</td><td>Yes</td><td>API connector.</td></tr><tr><td>Google UAC</td><td>Yes</td><td>API connector.</td></tr><tr><td>Meta</td><td>Partly</td><td>Modelled from installs on every ad account the connector can see, so it won''t match the receipts. The connector user lost access in May, nothing from Meta since.</td></tr><tr><td>Unity Ads</td><td>No</td><td>Installs only. See ENG-2362.</td></tr></tbody></table>', 'storage', 'current', 1, 'user_STAFF_2', '2025-08-14T16:20:00Z', '2025-08-14T16:20:00Z');
INSERT INTO confluence.confluence_page_versions (id, page_id, number, title, body, author_id, message, created_at)
VALUES ('ver_2d2606e59736e75505590efb813c6728', 'page_singular_cost_connectors', 1, 'Singular cost connectors', '<p>Which ad networks send cost into Singular. AD_SPEND_DAILY in Snowflake is built from Singular''s cost per network, and the marketing_ua amounts in FINANCE_LEDGER come from the same cost, so both have the gaps below. FINANCE_LEDGER books operating costs by month: marketing, salaries, AWS and the rest are dated to the last day of the month they belong to, not the day the money moved.</p><table><tbody><tr><th>Network</th><th>Cost into Singular</th><th>Notes</th></tr><tr><td>Adjoe</td><td>Yes</td><td>Loaded from the monthly invoice after any credit.</td></tr><tr><td>AppLovin</td><td>Yes</td><td>API connector.</td></tr><tr><td>Google UAC</td><td>Yes</td><td>API connector.</td></tr><tr><td>Meta</td><td>Partly</td><td>Modelled from installs on every ad account the connector can see, so it won''t match the receipts. The connector user lost access in May, nothing from Meta since.</td></tr><tr><td>Unity Ads</td><td>No</td><td>Installs only. See ENG-2362.</td></tr></tbody></table>', 'user_STAFF_2', NULL, '2025-08-14T16:20:00Z');
INSERT INTO confluence.confluence_pages (id, space_id, parent_id, title, body, body_format, status, version, author_id, created_at, updated_at)
VALUES ('page_ua_spend_buckets', 'space_PROD', 'page_prod_home', 'UA spend buckets', '<p>Domino Delights incent test, Q2 2025.</p><p>Fundraising bucket: Adjoe and AppLovin, because we run them to show early ROAS to investors. Real UA: Meta and Google.</p>', 'storage', 'current', 1, 'user_EMPLOYEE_0008', '2025-04-24T17:10:00Z', '2025-04-24T17:10:00Z');
INSERT INTO confluence.confluence_page_versions (id, page_id, number, title, body, author_id, message, created_at)
VALUES ('ver_71b50deb486515685f3f326ef5edadb9', 'page_ua_spend_buckets', 1, 'UA spend buckets', '<p>Domino Delights incent test, Q2 2025.</p><p>Fundraising bucket: Adjoe and AppLovin, because we run them to show early ROAS to investors. Real UA: Meta and Google.</p>', 'user_EMPLOYEE_0008', NULL, '2025-04-24T17:10:00Z');

-- ===================== LINEAR (comment on base ENG-2362) =====================
INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence)
VALUES ('cmt_6b4787a755ac66787e8c', 'ENG-2362', 'usr_eac7fcafa75e4935', NULL, 'While setting up campaign tracking: Unity Ads cost has never come into Singular. The Unity reporting user has no billing access, so Singular only gets installs. Real Unity spend is on the statements Frederick saves in the UA statements folder, for our account and the Calm Play one.', false, '2025-08-13T17:42:00Z', '2025-08-13T17:42:00Z', 1);
UPDATE linear.linear_issues SET updated_at = '2025-08-13T17:42:00Z' WHERE id = 'ENG-2362';

