INSERT INTO trello.trello_cards (id, name, "idBoard", "idList", "desc", pos, closed, due, "dueComplete", "idMembers_json", "idLabels_json", "idShort", "shortLink", "shortUrl", url, "dateLastActivity", cover_json, badges_json, start, "idAttachmentCover")
VALUES ('68c99c40e5d9eb6f3a988838', 'UA spend buckets - ZM3D bridge test', '66da196af476ab78deaa0cef', '66da196af476ab78deaa0cf7', E'Following the thread in executives yesterday, we keep two buckets.\n\nFundraising: spend we run only to get CPI and retention numbers for the bridge deck. That is the UK iOS test on Unity (phone and tablet campaigns) and the Meta ZM_UK campaigns, from Sep 12 on.\n\nReal UA: everything else, including playables, creative tests and anything that ran before Sep 12.\n\nSpend goes in the bucket that applied on the day it was spent. If one charge or statement line covers both, split it by campaign.\n\nThis replaces the DD incent test split from April. For the data room, nothing before Sep 12 is fundraising.', 65536.0, false, NULL, false, '["4b4a68fc0fec0b254e4f9d8e", "PERSON_6094_TRELLO_USER_ID"]', '[]', 42, NULL, NULL, 'https://PERSON_6092_TRELLO_USERNAME.com/c/45504625/42-ua-spend-buckets-zm3d-bridge-test', '2025-09-22T18:30:00Z', NULL, '{"attachments": 0, "attachmentsByType": {"trello": {"board": 0, "card": 0}}, "checkItems": 0, "checkItemsChecked": 0, "checkItemsEarliestDue": null, "comments": 1, "description": true, "due": null, "dueComplete": false, "externalSource": null, "fogbugz": "", "lastUpdatedByAi": false, "location": false, "maliciousAttachments": 0, "start": null, "votes": 0}', NULL, NULL);
